import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"Synthetic diagnosis lab","description":"Mobile Inspector development documentation · Synthetic diagnosis lab","frontmatter":{"title":"Synthetic diagnosis lab","description":"Mobile Inspector development documentation · Synthetic diagnosis lab"},"headers":[],"relativePath":"en/tutorials/diagnosis.md","filePath":"en/tutorials/diagnosis.md"}'),n={name:"en/tutorials/diagnosis.md"};function o(r,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="synthetic-diagnosis-lab" tabindex="-1">Synthetic diagnosis lab <a class="header-anchor" href="#synthetic-diagnosis-lab" aria-label="Permalink to &quot;Synthetic diagnosis lab&quot;">​</a></h1><p>This is a source-only synthetic lab for incident orchestration. It is not an operational model setup guide. Current automatic diagnosis is false; Codex admission is <code>UNSUPPORTED_SANDBOX</code>, provider compatibility is unaccepted and M4 repair is unimplemented.</p><h2 id="run-fake-runners-only" tabindex="-1">Run fake runners only <a class="header-anchor" href="#run-fake-runners-only" aria-label="Permalink to &quot;Run fake runners only&quot;">​</a></h2><p>From the authorized complete source checkout, with locked dependencies installed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify:diagnosis</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify:responses</span></span></code></pre></div><p>Default runs own temporary synthetic fixtures and fake runners/providers. They do not contact a real model, read business accounts or configure global authentication. They are not present in an installed runtime tarball.</p><h2 id="what-to-inspect" tabindex="-1">What to inspect <a class="header-anchor" href="#what-to-inspect" aria-label="Permalink to &quot;What to inspect&quot;">​</a></h2><p>Check that observations and task states remain separate, cancellation invalidates old callbacks, limits/quiet windows reject repeated work, and CLI/viewer/MCP share the same safe failure authority. A diagnosis result is a hypothesis and never edit permission. Failure details are fixed stage/code enums; raw provider text is excluded.</p><p>Local tests can validate strict JSON shape, scoped references, malformed output rejection, one-POST bounds and owned cleanup. They cannot certify a provider, host tool inventory, source cause, device behavior or live deployment.</p><h2 id="stop-at-the-boundary" tabindex="-1">Stop at the boundary <a class="header-anchor" href="#stop-at-the-boundary" aria-label="Permalink to &quot;Stop at the boundary&quot;">​</a></h2><p>Do not add a real policy flag to these commands without separate explicit authorization. A real request may be billed; failed compatibility is not permission for retries, protocol relaxation, provider fallback or authentication changes. Do not weaken the Codex gate to make the lab appear operational. For useful model-free inspection use <a href="./../reference/incidents">incidents</a> and <a href="./../reference/mcp">the five MCP tools</a>.</p>`,11)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
